local ActionDarkDreamMainLevelNewFinalCell = Class('ActionDarkDreamMainLevelNewFinalCell')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local UIModule = CS.Engine.UI.UIModule
local CDTimerModule = CS.Engine.Modules.CDTimerModule

function ActionDarkDreamMainLevelNewFinalCell:__init()

end

function ActionDarkDreamMainLevelNewFinalCell:__delete()

end

function ActionDarkDreamMainLevelNewFinalCell:Awake()
	SetButtonAction(self.BtnNode.gameObject, Bind(self,self.OnBtnNodeClick))
end

function ActionDarkDreamMainLevelNewFinalCell:OnBtnNodeClick()
	if checkNumber(self.data.passed) == 1 then
		UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
		return
	end
	
	local homeDojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
	local time = homeDojo:GetBossRemainTime()
	if time <= 0 then
		GameUtils.Toast(localize("挑战已结束，排行榜结算中"))
		return
	end
	
	if self.isUnLock then
		UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
	else
		GameUtils.Toast(localize("请通关前置关卡"))
	end
end

function ActionDarkDreamMainLevelNewFinalCell:RefreshShow(data, groupId, index, callBack)
	CfUtils.SetActive(self.UIFX_LoopGlow.gameObject,false)
	self.data = data
	self.groupId = groupId
	self.clickCallBack = callBack
	self.index = index
	
	local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.data.id)
	self.nodeVo = nodeVo
	
	local isPass = checkNumber(self.data.passed) == 1
	
	if isPass then
		CfUtils.SetUISwitchImage(self.ImgBg,2)
		CfUtils.SetUISwitchImage(self.ImgIcon,2)
		CfUtils.SetActive(self.StatusLock.gameObject,false)
		CfUtils.SetActive(self.StatusUnlock.gameObject,true)
		local myRank = self:GetMyRank()
		CfUtils.FillText(self.TextRank, myRank)
	else
		local isUnLock = checkNumber(nodeVo.unlockPlace) == 0 and true or ChaoticRecallUtils.GetIsPassById(nodeVo.groupId,nodeVo.unlockPlace)
		self.isUnLock = isUnLock
		CfUtils.SetActive(self.StatusLock.gameObject,not isUnLock)
		CfUtils.SetActive(self.StatusUnlock.gameObject,isUnLock)
		CfUtils.SetUISwitchImage(self.ImgBg,isUnLock and 2 or 1)
		CfUtils.SetUISwitchImage(self.ImgIcon,isUnLock and 2 or 1)
	end
	self:SetTimeShow()
end

function ActionDarkDreamMainLevelNewFinalCell:SetTimeShow()
	self:RemoveTimer()
	local homeDojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
	local time = homeDojo:GetBossRemainTime()
	if time > 0 then
		CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS4(time))
		self.bossTimer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
			if count > 0 then
				CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS4(count))
			else
				CDTimerModule.GetInstance():RemoveCD(self.bossTimer)
				self.bossTimer = nil
				CfUtils.FillText(self.TextTime,localize("挑战已结束，排行榜结算中"))
			end
		end, time, false, true)
	else
		CfUtils.FillText(self.TextTime,localize("挑战已结束，排行榜结算中"))
	end
end

function ActionDarkDreamMainLevelNewFinalCell:RemoveTimer()
	if isNotNull(self.bossTimer) then
		CDTimerModule.GetInstance():RemoveCD(self.bossTimer)
		self.bossTimer = nil
	end
end

function ActionDarkDreamMainLevelNewFinalCell:GetMyRank()
	local homeDojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
	local myRank = homeDojo:GetMyRank(self.index)
	return "No."..myRank
end

function ActionDarkDreamMainLevelNewFinalCell:SetCallBack()

end

function ActionDarkDreamMainLevelNewFinalCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:RemoveTimer()
	self:Delete()
end

return ActionDarkDreamMainLevelNewFinalCell